output_text:
[
  {
    "id": "no_carts_single_file",
    "text": "Shopping carts are prohibited in single-file aisles, identified by a corridor width of one cell in either direction.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_carts_between_shelves",
    "text": "Carts may not be taken into aisles where shelves are directly on both sides of the shopper.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "betweenOpposingShelves"
        ]
      }
    }
  },
  {
    "id": "no_enter_cart_incompatible_aisle",
    "text": "It is forbidden to move a cart into a narrow shelf aisle that is intended for pedestrians only.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartIncompatibleAisle": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        }
      },
      "events": {
        "enterCartIncompatibleAisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "cartIncompatibleAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterCartIncompatibleAisle"
    }
  },
  {
    "id": "park_at_narrow_aisle_mouth",
    "text": "When a shopper brings a cart to the wide mouth of a narrow shelf aisle, they are obliged to park or release the cart before continuing the aisle visit.",
    "abstraction": {
      "state_properties": {
        "wideOpenAisle": {
          "and": [
            {
              "gt": [
                "freeWidthH",
                2
              ]
            },
            {
              "gt": [
                "freeWidthV",
                2
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "narrowAisleMouth": {
          "and": [
            "at(3,3)",
            "wideOpenAisle"
          ]
        },
        "cartAtNarrowAisleMouth": {
          "and": [
            "narrowAisleMouth",
            "hasCart"
          ]
        }
      },
      "events": {
        "arriveWithCartAtNarrowAisleMouth": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "cartAtNarrowAisleMouth"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveWithCartAtNarrowAisleMouth",
      "discharge": {
        "not": "hasCart"
      }
    }
  },
  {
    "id": "reclaim_parked_cart",
    "text": "A shopper who parks a cart at the mouth of a pedestrian shelf aisle is obliged to reclaim that cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(3,3)",
        "cartAtBay": {
          "and": [
            "cartBay",
            "hasCart"
          ]
        },
        "noCartAtBay": {
          "and": [
            "cartBay",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "parkCartAtBay": {
          "pre": {
            "and": [
              "cartAtBay",
              "INTERACT"
            ]
          },
          "post": "noCartAtBay"
        },
        "retrieveCartAtBay": {
          "pre": {
            "and": [
              "noCartAtBay",
              "INTERACT"
            ]
          },
          "post": "cartAtBay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtBay",
      "discharge": "retrieveCartAtBay"
    }
  },
  {
    "id": "hands_free_shelf_pick",
    "text": "Interactions with shelves from a single-file shelf aisle must be done hands-free, without holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelfPickSlot": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "shelfPickSlot"
        ]
      }
    }
  },
  {
    "id": "park_only_wide_open",
    "text": "Carts may only be parked or released in wide open aisle space where they do not block shelves or a narrow passage.",
    "abstraction": {
      "state_properties": {
        "wideEnoughForCartParking": {
          "and": [
            {
              "gt": [
                "freeWidthH",
                2
              ]
            },
            {
              "gt": [
                "freeWidthV",
                2
              ]
            }
          ]
        },
        "legalCartParkingArea": {
          "and": [
            "wideEnoughForCartParking",
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "legalCartParkingArea"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_after_return_from_pedestrian_aisle",
    "text": "After returning from a pedestrian-only shelf aisle to the cart bay, the shopper is obliged to retrieve the parked cart.",
    "abstraction": {
      "state_properties": {
        "pedestrianShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartBay": "at(3,3)",
        "noCartAtBay": {
          "and": [
            "cartBay",
            {
              "not": "hasCart"
            }
          ]
        },
        "cartAtBay": {
          "and": [
            "cartBay",
            "hasCart"
          ]
        }
      },
      "events": {
        "returnFromPedestrianAisleToBay": {
          "pre": {
            "and": [
              "pedestrianShelfAisle",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "noCartAtBay"
        },
        "retrieveCartAtBay": {
          "pre": {
            "and": [
              "noCartAtBay",
              "INTERACT"
            ]
          },
          "post": "cartAtBay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnFromPedestrianAisleToBay",
      "discharge": "retrieveCartAtBay"
    }
  }
]
